import{K as e}from"./index-ClEiF4mV.js";var t={getGEXData:async t=>(await e.post(`/gex/api/gex-data`,t)).data,getUnderlyings:async t=>(await e.get(`/search/api/underlyings?exchange=${t}`)).data,getExpiries:async(t,n)=>(await e.get(`/search/api/expiries?exchange=${t}&underlying=${n}&instrumenttype=options`)).data,getGEXLevels:async(t,n)=>(await e.post(`/gex/api/gex-levels`,t,{signal:n})).data,getGEXHistory:async(t,n)=>(await e.post(`/gex/api/gex-history`,t,{signal:n})).data,getGEXGrid:async(t,n)=>(await e.post(`/gex/api/gex-history`,{...t,fields:`grid`},{signal:n})).data,addGEXSeries:async t=>(await e.post(`/gex/api/gex-series`,t)).data,removeGEXSeries:async t=>(await e.delete(`/gex/api/gex-series/${t}`)).data};export{t};